g.metadata:
{
  "schema": "ppt-master.semantic-table.v2",
  "x": 64, "y": 170, "width": 1152, "height": 382,
  "name": "chatgpt-codex-comparison",
  "strict_grid": true,
  "header_rows": 1,
  "column_widths": [1.2, 2.2, 2.6],
  "row_heights": [0.75, 1, 1, 1, 1],
  "style": {
    "font_family": "Microsoft YaHei",
    "font_size": 20,
    "header_font_size": 20,
    "header_fill": "#263238",
    "header_text": "#FFFFFF",
    "body_fill": "#FFFFFF",
    "body_text": "#263238",
    "band_row": false,
    "padding": 10,
    "valign": "middle"
  },
  "defaults": {
    "cell": {
      "padding": 10,
      "valign": "middle",
      "borders": {
        "left": {"style": "none"},
        "right": {"style": "none"},
        "top": {"style": "none"},
        "bottom": {"style": "solid", "color": "#D8DEE0", "width": 1}
      }
    }
  },
  "columns": [
    {"text": "比较维度", "align": "l", "bold": true},
    {"text": "ChatGPT", "align": "l", "bold": true},
    {"text": "Codex", "align": "l", "bold": true}
  ],
  "rows": [
    [
      {"text": "工作重心", "fill": "#FFFFFF", "bold": true},
      {"text": "解释、讨论与内容产出"},
      {"text": "理解代码库并完成变更", "fill": "#F2F5F5", "bold": true, "color": "#355F70"}
    ],
    [
      {"text": "主要上下文", "fill": "#FFFFFF", "bold": true},
      {"text": "问题、文件与通用知识"},
      {"text": "仓库、编辑器、终端与 Git", "fill": "#F2F5F5", "bold": true, "color": "#355F70"}
    ],
    [
      {"text": "典型交付", "fill": "#FFFFFF", "bold": true},
      {"text": "答案、方案与文档"},
      {"text": "代码变更、测试结果与 diff", "fill": "#F2F5F5", "bold": true, "color": "#355F70"}
    ],
    [
      {"text": "人的角色", "fill": "#FFFFFF", "bold": true},
      {"text": "判断内容是否有用"},
      {"text": "定义目标、审查变更、批准关键操作", "fill": "#F2F5F5", "bold": true, "color": "#355F70"}
    ]
  ]
}
